./research/discovery/20261015T024219Z-predictive-entropy-search-with-constraints.json:49033:        "text": "{
  "id": "AIMech:PredictiveEntropySearchWithConstraints",
  "name": "Predictive Entropy Search with Constraints",
  "concept_kind": "algorithm",
  "definition": "A Bayesian optimization algorithm for an unknown objective and unknown inequality constraints that selects evaluations using an approximation to information about the constrained minimizer location, combining posterior optimizer samples, finite feasibility and optimality indicators, Gaussian expectation propagation and taskwise predictive observation entropies.",
  "definition_evidence": [
    {
      "source_id": "hernandez2015",
      "locator": "Section 3, PDF pp. 3\u20135, Equations 6\u201316",
      "relation": "supports"
    }
  ],
  "claims": [
    {
      "claim_id": "constrained-optimizer-information-target",
      "kind": "mechanism",
      "statement": "The problem minimizes f(x) subject to c_k(x)>=0 for each constraint, with objective and constraints defined throughout the search domain. Assume posterior function draws have an attained feasible minimum and an almost surely unique minimizer or a specified measurable tie selection. At fixed data and model hyperparameters, the ideal acquisition targets I(X_star;Y|D,x), where X_star is that constrained minimizer location and Y contains the prospective objective and constraint observations. When the entropy terms are well-defined, this equals H(Y|D,x)-E_X_star[H(Y|D,x,X_star)]. The acquisition does not require an already observed feasible incumbent. That property does not specify how to handle a posterior function draw with no feasible point or no attained minimum.",
      "evidence": [
        {
          "source_id": "hernandez2015",
          "locator": "PDF p. 1, Equation 1 and introductory motivation; Section 3, PDF p. 3, Equations 6\u20137",
          "relation": "supports"
        },
        {
          "source_id": "hernandez2016",
          "locator": "Section 4, PDF p. 13, Equations 7\u20138 and the optimizer sampling definition",
          "relation": "supports"
        }
      ]
    },
    {
      "claim_id": "approximate-constrained-optimizer-sampling",
      "kind": "mechanism",
      "statement": "The practical method models the objective and constraints with independent Gaussian processes and independent Gaussian observation noise. It approximates the expectation over X_star with a finite average: draw approximate posterior functions and numerically minimize the sampled objective under the sampled constraints. The described sampler uses a finite basis approximation for stationary covariance functions, so the generated optimizer samples are approximate. Sampling GP hyperparameters and averaging their acquisition scores is an additional approximation, not in general the information obtained by first marginalizing predictive distributions over hyperparameters. The source does not guarantee that its numerical searches find every global optimizer.",
      "evidence": [
        {
          "source_id": "hernandez2015",
          "locator": "Section 3, PDF p. 3, model assumptions and paragraph following Equation 8",
          "relation": "supports"
        },
        {
          "source_id": "hernandez2016",
          "locator": "Sections 4.1, 4.3 and 4.6, PDF pp. 14, 20\u201322, Equation 21; Appendix B.3, PDF p. 49",
          "relation": "supports"
        }
      ]
    },
    {
      "claim_id": "finite-feasibility-and-optimality-indicators",
      "kind": "mechanism",
